const st = app.status || { plan: [], stamps: 0, daysLeft: null, perDay: 1, today: T };
const state = { done: app.done || {}, tests: app.tests || {} };
const unit = app.unit || C.unit(1) || { n: 1, gn: '', es: '', days: [], test: [] };
/* 0 while the level's syllabus has not loaded: the card then says "En preparación" instead of "Semana 1 de 0" */
const unitCount = (app.progress && app.progress.units && app.progress.units.length) || C.units().length || 0;
const sessions = (st.plan || []).filter((p) => p.unit === unit.n).slice(0, SPOTS.length);
